INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 1, 126401, 2002, 1.47, "2023/06/30 12:00:00", 1, 2, -470.0, "2023/09/22 14:59:59", "クローチェ", "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 0.0, 10001);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 2, 126401, 2002, 2.15, "2023/06/30 12:00:00", 2, 1, -470.0, "2023/09/22 14:59:59", "クローチェ", "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 0.0, 10002);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 2, 126501, 2002, 0.0, "2023/06/30 12:00:00", 1, 2, -470.0, "2023/09/22 14:59:59", "ライラエル", "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 0.0, 10003);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (1, 1, 126501, 2002, 0.0, "2023/06/30 12:00:00", 2, 1, -470.0, "2023/09/22 14:59:59", "ライラエル", "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 0.0, 10004);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 2, 127702, 2002, 0.0, "2023/09/15 15:00:00", 1, 2, -470.0, "2023/12/22 14:59:59", "リンド", "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 0.0, 10005);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 2, 127702, 2002, 0.0, "2023/09/15 15:00:00", 2, 2, -470.0, "2023/12/22 14:59:59", "リンド", "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 0.0, 10006);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 1, 127802, 2002, 0.0, "2023/09/15 15:00:00", 1, 1, -470.0, "2023/12/22 14:59:59", "ヴルム", "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 0.0, 10007);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (2, 2, 127802, 2002, 6.5, "2023/09/15 15:00:00", 2, 1, -470.0, "2023/12/22 14:59:59", "ヴルム", "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 0.0, 10008);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, 2, 129602, 2002, 0.0, "2023/12/15 15:00:00", 1, 1, -470.0, "2024/03/22 14:59:59", "アネモネ", "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 0.0, 10009);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, 2, 129602, 2002, 0.0, "2023/12/15 15:00:00", 2, 1, -470.0, "2024/03/22 14:59:59", "アネモネ", "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 0.0, 10010);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, 1, 129701, 2002, 0.0, "2023/12/15 15:00:00", 1, 1, -470.0, "2024/03/22 14:59:59", "ネフィ=ネラ", "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 0.0, 10011);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (3, 2, 129701, 2002, 6.2, "2023/12/15 15:00:00", 2, 1, -470.0, "2024/03/22 14:59:59", "ネフィ=ネラ", "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 0.0, 10012);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 3, 130301, 2002, 3.1, "2024/03/15 15:00:00", 1, 5, -470.0, "2024/06/22 14:59:59", "カノン", "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 0.0, 10013);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 3, 130301, 2002, 6.15, "2024/03/15 15:00:00", 2, 2, -470.0, "2024/06/22 14:59:59", "カノン", "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 0.0, 10014);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 2, 130401, 2002, 0.0, "2024/03/15 15:00:00", 1, 2, -470.0, "2024/06/22 14:59:59", "ナーナ", "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 0.0, 10015);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (4, 2, 130401, 2002, 3.35, "2024/03/15 15:00:00", 2, 1, -470.0, "2024/06/22 14:59:59", "ナーナ", "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 0.0, 10016);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 1, 130502, 2002, 0.0, "2024/06/15 15:00:00", 1, 1, -470.0, "2024/09/22 14:59:59", "ホウオウ", "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 0.0, 10017);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 2, 130502, 2002, 3.18, "2024/06/15 15:00:00", 2, 1, -470.0, "2024/09/22 14:59:59", "ホウオウ", "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 0.0, 10018);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 4, 130503, 2002, 0.0, "2024/06/15 15:00:00", 3, 4, -470.0, "2024/09/22 14:59:59", "ホウオウ", "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 0.0, 10019);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 1, 123301, 2002, 4.9, "2024/06/15 15:00:00", 1, 2, -470.0, "2024/09/22 14:59:59", "ネア", "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 0.0, 10020);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (5, 1, 123301, 2002, 4.8, "2024/06/15 15:00:00", 2, 2, -470.0, "2024/09/22 14:59:59", "ネア", "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 0.0, 10021);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 3, 133301, 2002, 4.922, "2024/09/15 15:00:00", 1, 1, -470.0, "2024/12/22 14:59:59", "カリザ", "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 0.0, 10022);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 3, 133301, 2002, 9.638, "2024/09/15 15:00:00", 2, 5, -470.0, "2024/12/22 14:59:59", "カリザ", "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 0.0, 10023);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 1, 133401, 2002, 2.88, "2024/09/15 15:00:00", 1, 2, -470.0, "2024/12/22 14:59:59", "ミーア", "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 0.0, 10024);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (6, 5, 133401, 2002, 4.818, "2024/09/15 15:00:00", 2, 1, -470.0, "2024/12/22 14:59:59", "ミーア", "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 0.0, 10025);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 2, 133002, 2002, 1.78, "2024/12/15 15:00:00", 1, 1, -470.0, "2025/03/22 14:59:59", "グレイス", "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 0.0, 10026);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 1, 133002, 2002, 6.15, "2024/12/15 15:00:00", 2, 7, -470.0, "2025/03/22 14:59:59", "グレイス", "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 0.0, 10027);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 6, 133102, 2002, 4.28, "2024/12/15 15:00:00", 1, 2, -470.0, "2025/03/22 14:59:59", "ヴァイオレット", "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 0.0, 10028);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (7, 1, 133102, 2002, 0.0, "2024/12/15 15:00:00", 2, 1, -470.0, "2025/03/22 14:59:59", "ヴァイオレット", "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 0.0, 10029);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, 2, 136902, 2002, 5.53, "2025/03/15 15:00:00", 1, 1, -470.0, "2025/06/23 14:59:59", "ルルィ", "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 0.0, 10030);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, 9, 136902, 2002, 6.05, "2025/03/15 15:00:00", 2, 7, -470.0, "2025/06/23 14:59:59", "ルルィ", "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 0.0, 10031);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, 2, 137001, 2002, 0.0, "2025/03/15 15:00:00", 1, 1, -470.0, "2025/06/23 14:59:59", "デュラン", "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 0.0, 10032);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (8, 2, 137001, 2002, 0.0, "2025/03/15 15:00:00", 2, 1, -470.0, "2025/06/23 14:59:59", "デュラン", "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 0.0, 10033);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, 2, 135902, 2002, 0.0, "2025/06/16 15:00:00", 1, 2, -470.0, "2025/09/23 14:59:59", "サツキ", "おう\n好きなもん持ってきな", 0.0, 10034);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, 1, 135902, 2002, 4.935, "2025/06/16 15:00:00", 2, 6, -470.0, "2025/09/23 14:59:59", "サツキ", "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 0.0, 10035);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, 2, 135802, 2002, 7.441, "2025/06/16 15:00:00", 1, 5, -470.0, "2025/09/23 14:59:59", "ユキノ", "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 0.0, 10036);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (9, 7, 135802, 2002, 0.0, "2025/06/16 15:00:00", 2, 7, -470.0, "2025/09/23 14:59:59", "ユキノ", "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 0.0, 10037);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, 2, 130901, 2002, 2.295, "2025/09/16 15:00:00", 1, 2, -470.0, "2025/12/22 14:59:59", "クルル", "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 0.0, 10038);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, 1, 130901, 2002, 6.281, "2025/09/16 15:00:00", 2, 6, -470.0, "2025/12/22 14:59:59", "クルル", "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 0.0, 10039);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, 2, 137701, 2002, 5.549, "2025/09/16 15:00:00", 1, 1, -470.0, "2025/12/22 14:59:59", "ヴォルガーノ", "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 0.0, 10040);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (10, 3, 137701, 2002, 2.64, "2025/09/16 15:00:00", 2, 6, -470.0, "2025/12/22 14:59:59", "ヴォルガーノ", "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 0.0, 10041);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, 7, 132801, 2002, 7.642, "2025/12/15 15:00:00", 1, 4, -470.0, "2026/03/23 11:59:59", "ライラエル", "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 0.0, 10042);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, 1, 132802, 2002, 0.0, "2025/12/15 15:00:00", 2, 1, -470.0, "2026/03/23 11:59:59", "ライラエル", "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 0.0, 10043);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, 1, 134502, 2002, 0.0, "2025/12/15 15:00:00", 1, 1, -470.0, "2026/03/23 11:59:59", "クローチェ", "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 0.0, 10044);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (11, 2, 134501, 2002, 3.72, "2025/12/15 15:00:00", 2, 1, -470.0, "2026/03/23 11:59:59", "クローチェ", "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 0.0, 10045);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, 2, 138201, 2002, 4.991, "2026/03/16 12:00:00", 1, 1, -470.0, "2026/06/22 11:59:59", "ネフィ＝ネラ", "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 0.0, 10046);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, 1, 138201, 2002, 3.877, "2026/03/16 12:00:00", 2, 4, -470.0, "2026/06/22 11:59:59", "ネフィ＝ネラ", "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 0.0, 10047);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, 4, 136001, 2002, 1.71, "2026/03/16 12:00:00", 1, 6, -470.0, "2026/06/22 11:59:59", "アラクネ", "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 0.0, 10048);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (12, 5, 136001, 2002, 5.32, "2026/03/16 12:00:00", 2, 2, -470.0, "2026/06/22 11:59:59", "アラクネ", "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 0.0, 10049);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (13, 9, 135401, 2002, 3.727, "2026/06/15 12:00:00", 1, 4, -470.0, "2026/09/22 11:59:59", "アネモネ", "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 0.0, 10050);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (13, 7, 135401, 2002, 7.213, "2026/06/15 12:00:00", 2, 9, -470.0, "2026/09/22 11:59:59", "アネモネ", "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 0.0, 10051);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES (13, 1, 135301, 2002, 1.874, "2026/06/15 12:00:00", 1, 2, -470.0, "2026/09/22 11:59:59", "クリア", "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 0.0, 10052);
